SELECT id, customer_id, plan, status, AVG(monthly_fee) OVER (PARTITION BY plan, status ORDER BY monthly_fee, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_avg_monthly_fee, MAX(monthly_fee) OVER (PARTITION BY plan, status ORDER BY monthly_fee, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_max_monthly_fee, SUM(monthly_fee) OVER (PARTITION BY plan, status ORDER BY monthly_fee, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) AS last3_sum_monthly_fee, NTILE(5) OVER (PARTITION BY status ORDER BY monthly_fee, id) AS monthly_fee_bucket FROM subscriptions WHERE monthly_fee < 230
